/*
	pi=4 #genuary17 #genuary #genuary2516 
	https://openprocessing.org/sketch/2515372
	What happens if pi=4?
	#p5js #creativecoding #generativeart 
*/

let S, shapes, CLRS;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("spiral looking shapes of diffwerent sizes and color combining lines from an inner points of a circle to outer points, where outer points are geenrated as pi=4");
	S = max(width, height)/random(8, 18);
	strokeWeight(3);
	noFill();

	colorMode(HSB, 1)
	CLRS = getRandPalette(~~random(6, 18));

	loop();
}

function draw() {
	for (let i = 0; i < random(10, 30); i++) background(CLRS[0])
	// const ctx = drawingContext;

	const shapes = []
	for (let x = S/2; x < width - S/4; x += S) {		
		for (let y = S/2; y < height - S/4; y += S) {
			shapes.push({x: random(x-S/4, x+S/4), y: random(y-S/4, y+S/4)});
		}
	}

	shuffle(shapes, true); // to be drawn in chaos order (not only tl to br)

	for (let sh of shapes) {
		push()
		translate(sh.x, sh.y)
		rotate(random(TAU))
		stroke(random(CLRS))
		const scl = random(0.7, 2.8);
		strokeWeight(2 * scl);
		drawSpiral(0, 0, scl * S);
		pop()
	}

	// noLoop() removed for animation
}

function drawSpiral(cx, cy, r) {
	const rf = random(0.5, 0.9);

	const num = random(4, 50);
	for (let  i = 0; i <= num; i++) {
		const f = i / num;

		const a = 2 * 4 * f; // outer radius: PI = 4
		const x1 = cx + cos(a) * r;
		const y1 = cy + sin(a) * r;
		// circle(x1, y1, 10)

		const aa = 2 * PI * f; // inner radius: PI = 3.1415..
		const rr = lerp(r, r * rf, f); // lerp inner radius to outer
		const x2 = cx + cos(aa) * rr;
		const y2 = cy + sin(aa) * rr;
		// circle(x2, y2, 10)

		line(x1, y1, x2, y2);
	}

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton != RIGHT) setup();
}

function getRandPalette(num = 6) {
	let arr = [];

	const numGen = random(num, num * 1.5);
	const clrHueStart = random();
	for (let i = 0; i < numGen; i++) arr.push(color((clrHueStart + i/numGen)%1, random(0.2, 0.7), random(), random(0.4, 0.9)));
	for (let  i = 0; i < random(arr.length); i++) arr.push(arr.shift());
	while (arr.length > num) arr.shift();

	return arr;
}
